package com.srm.inventory.controller;
import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class ProductControllerIntegrationTest { @Autowired MockMvc mvc; @Test void createsAndListsProduct() throws Exception {String json="{\"name\":\"Test Pen\",\"sku\":\"PEN-999\",\"price\":2.50,\"stockQuantity\":10,\"reorderLevel\":3,\"category\":\"Stationery\"}";mvc.perform(post("/api/products").contentType(MediaType.APPLICATION_JSON).content(json)).andExpect(status().isCreated()).andExpect(jsonPath("$.sku").value("PEN-999"));mvc.perform(get("/api/products?q=PEN-999")).andExpect(status().isOk()).andExpect(jsonPath("$[0].name").value("Test Pen"));} }
